window.V10LAB={"orders_core.py": "\"\"\"Lõi nghiệp vụ dùng chung cho Lab tích hợp (API → MCP → multi-agent).\nKhông gọi mạng: dữ liệu giả trong bộ nhớ để test được.\"\"\"\nREFUND_LIMIT = 500_000  # VND — quá mức này phải escalate cho người (hook tất định, không nhờ prompt)\nCUSTOMERS = {\"a@b.vn\": \"C001\", \"0901234567\": \"C002\"}\nORDERS = {\"812\": {\"customer\": \"C001\", \"total\": 320_000, \"status\": \"delivered\"},\n          \"90\": {\"customer\": \"C002\", \"total\": 1_200_000, \"status\": \"delivered\"},\n          \"77\": {\"customer\": \"C001\", \"total\": 150_000, \"status\": \"shipping\"}}\nPOLICY = {\"refund_window_days\": 30, \"needs_verified_customer\": True}\n\ndef err(category, message, retryable=False, **extra):\n    \"\"\"Structured error (lỗi có cấu trúc): agent đọc được category + isRetryable.\"\"\"\n    return {\"isError\": True, \"errorCategory\": category, \"isRetryable\": retryable, \"message\": message, **extra}\n\nclass Session:\n    def __init__(self):\n        self.customer_id = None   # prerequisite: phải find_customer trước khi refund\n\n    def find_customer(self, key):\n        cid = CUSTOMERS.get(key)\n        if not cid:\n            return err(\"not_found\", f\"Không có khách với {key!r}\")\n        self.customer_id = cid\n        return {\"customer_id\": cid}\n\n    def get_order(self, order_id):\n        o = ORDERS.get(str(order_id))\n        if not o:\n            return err(\"not_found\", f\"Không có đơn {order_id}\")\n        return {\"order_id\": str(order_id), **o}\n\n    def refund(self, order_id, amount):\n        if self.customer_id is None:\n            return err(\"prerequisite\", \"Phải xác minh khách (find_customer) trước khi hoàn tiền\")\n        o = ORDERS.get(str(order_id))\n        if not o:\n            return err(\"not_found\", f\"Không có đơn {order_id}\")\n        if o[\"customer\"] != self.customer_id:\n            return err(\"permission\", \"Đơn không thuộc khách đã xác minh\")\n        if amount > o[\"total\"]:\n            return err(\"validation\", \"Số tiền hoàn lớn hơn giá trị đơn\")\n        if amount > REFUND_LIMIT:\n            return err(\"escalation\", \"Vượt hạn mức tự động, chuyển cho nhân viên\", escalate=True)\n        return {\"refunded\": amount, \"order_id\": str(order_id)}\n\nTOOLS = [\n    {\"name\": \"find_customer\", \"description\": \"Xác minh khách bằng email hoặc số điện thoại. BẮT BUỘC gọi trước refund.\",\n     \"input_schema\": {\"type\": \"object\", \"properties\": {\"key\": {\"type\": \"string\"}}, \"required\": [\"key\"]}},\n    {\"name\": \"get_order\", \"description\": \"Xem đơn theo order_id (chỉ đọc).\",\n     \"input_schema\": {\"type\": \"object\", \"properties\": {\"order_id\": {\"type\": \"string\"}}, \"required\": [\"order_id\"]}},\n    {\"name\": \"refund\", \"description\": \"Hoàn tiền cho đơn của khách ĐÃ xác minh. Số tiền VND.\",\n     \"input_schema\": {\"type\": \"object\", \"properties\": {\"order_id\": {\"type\": \"string\"}, \"amount\": {\"type\": \"integer\"}},\n                      \"required\": [\"order_id\", \"amount\"]}},\n]\n\ndef dispatch(session, name, args):\n    fn = {\"find_customer\": session.find_customer, \"get_order\": session.get_order, \"refund\": session.refund}.get(name)\n    if not fn:\n        return err(\"unknown_tool\", f\"Tool {name} không tồn tại\")\n    try:\n        return fn(**args)\n    except TypeError as e:\n        return err(\"validation\", str(e))\n", "step1_api_loop.py": "\"\"\"Bước 1 — Agentic loop thuần Messages API: lặp tới khi stop_reason == 'end_turn'.\"\"\"\nimport json, sys\nimport anthropic\nfrom orders_core import Session, TOOLS, dispatch\nMODEL = \"claude-sonnet-4-5\"\n\ndef run(prompt, client=None, max_turns=8):\n    client = client or anthropic.Anthropic()\n    s, msgs = Session(), [{\"role\": \"user\", \"content\": prompt}]\n    for _ in range(max_turns):\n        r = client.messages.create(model=MODEL, max_tokens=1024, tools=TOOLS, messages=msgs,\n                                   system=\"Bạn là agent CSKH. Luôn xác minh khách trước khi hoàn tiền.\")\n        msgs.append({\"role\": \"assistant\", \"content\": r.content})\n        if r.stop_reason != \"tool_use\":\n            return \"\".join(b.text for b in r.content if b.type == \"text\"), msgs\n        results = []\n        for b in r.content:\n            if b.type == \"tool_use\":\n                out = dispatch(s, b.name, b.input)\n                results.append({\"type\": \"tool_result\", \"tool_use_id\": b.id, \"content\": json.dumps(out, ensure_ascii=False),\n                                \"is_error\": bool(out.get(\"isError\"))})\n        msgs.append({\"role\": \"user\", \"content\": results})\n    return \"[dừng: quá max_turns]\", msgs\n\nif __name__ == \"__main__\":\n    print(run(sys.argv[1] if len(sys.argv) > 1 else \"Tôi là a@b.vn, hoàn 100000đ cho đơn 812\")[0])\n", "step2_mcp_server.py": "\"\"\"Bước 2 — Đưa cùng nghiệp vụ thành MCP server (FastMCP, stdio).\nĐăng ký trong .mcp.json: {\"mcpServers\":{\"orders\":{\"command\":\"python\",\"args\":[\"labs/integrated/step2_mcp_server.py\"]}}}\"\"\"\nfrom mcp.server.fastmcp import FastMCP\nfrom orders_core import Session\n\nmcp = FastMCP(\"orders\")\n_session = Session()   # 1 phiên / tiến trình server\n\n@mcp.tool()\ndef find_customer(key: str) -> dict:\n    \"\"\"Xác minh khách bằng email hoặc số điện thoại. BẮT BUỘC gọi trước refund.\"\"\"\n    return _session.find_customer(key)\n\n@mcp.tool()\ndef get_order(order_id: str) -> dict:\n    \"\"\"Xem đơn theo order_id (chỉ đọc).\"\"\"\n    return _session.get_order(order_id)\n\n@mcp.tool()\ndef refund(order_id: str, amount: int) -> dict:\n    \"\"\"Hoàn tiền cho đơn của khách ĐÃ xác minh. Trả lỗi có cấu trúc (errorCategory, isRetryable).\"\"\"\n    return _session.refund(order_id, amount)\n\n@mcp.resource(\"policy://refund\")\ndef refund_policy() -> str:\n    \"\"\"Resource: chính sách hoàn tiền để agent đọc thay vì đoán.\"\"\"\n    from orders_core import POLICY, REFUND_LIMIT\n    return f\"Hạn hoàn tiền {POLICY['refund_window_days']} ngày; tự động tối đa {REFUND_LIMIT} VND; cần xác minh khách.\"\n\nif __name__ == \"__main__\":\n    mcp.run()\n", "step3_multi_agent.py": "\"\"\"Bước 3 — Coordinator + 2 subagent chạy song song (hub-and-spoke).\nMỗi subagent nhận context TƯỜNG MINH (không thừa hưởng lịch sử), ít tool đúng vai,\ntrả kết quả có cấu trúc; coordinator gộp và ghi rõ chỗ thiếu (gaps) thay vì bịa.\"\"\"\nfrom concurrent.futures import ThreadPoolExecutor\nfrom orders_core import Session, POLICY, REFUND_LIMIT, err\n\ndef policy_agent(task):\n    \"\"\"Subagent chỉ đọc chính sách — không có tool refund.\"\"\"\n    return {\"agent\": \"policy\", \"ok\": True,\n            \"facts\": {\"window_days\": POLICY[\"refund_window_days\"], \"auto_limit\": REFUND_LIMIT}}\n\ndef billing_agent(task):\n    \"\"\"Subagent billing: 3 tool, chạy trong Session riêng.\"\"\"\n    s = Session()\n    who = s.find_customer(task[\"customer_key\"])\n    if who.get(\"isError\"):\n        return {\"agent\": \"billing\", \"ok\": False, \"error\": who}\n    order = s.get_order(task[\"order_id\"])\n    if order.get(\"isError\"):\n        return {\"agent\": \"billing\", \"ok\": False, \"error\": order}\n    res = s.refund(task[\"order_id\"], task[\"amount\"])\n    return {\"agent\": \"billing\", \"ok\": not res.get(\"isError\"), \"order\": order, \"result\": res}\n\ndef coordinator(request, timeout=10):\n    tasks = {\"policy\": (policy_agent, {\"question\": \"refund policy\"}),\n             \"billing\": (billing_agent, {k: request[k] for k in (\"customer_key\", \"order_id\", \"amount\")})}\n    out, gaps = {}, []\n    with ThreadPoolExecutor(max_workers=len(tasks)) as ex:   # song song: phát cả 2 cùng lúc\n        futs = {name: ex.submit(fn, ctx) for name, (fn, ctx) in tasks.items()}\n        for name, f in futs.items():\n            try:\n                out[name] = f.result(timeout=timeout)\n            except Exception as e:   # subagent lỗi → ghi gap, không làm sập cả hệ\n                out[name] = {\"agent\": name, \"ok\": False, \"error\": err(\"subagent_failure\", str(e), retryable=True)}\n    for name, r in out.items():\n        if not r.get(\"ok\"):\n            gaps.append({\"agent\": name, **(r.get(\"error\") or r.get(\"result\") or {})})\n    b = out.get(\"billing\", {})\n    escalate = any(g.get(\"escalate\") for g in gaps) or bool((b.get(\"result\") or {}).get(\"escalate\"))\n    status = \"done\" if not gaps else (\"escalated\" if escalate else \"partial\")\n    return {\"status\": status, \"results\": out, \"gaps\": gaps}\n\nif __name__ == \"__main__\":\n    import json\n    for req in ({\"customer_key\": \"a@b.vn\", \"order_id\": \"812\", \"amount\": 100_000},\n                {\"customer_key\": \"0901234567\", \"order_id\": \"90\", \"amount\": 900_000},\n                {\"customer_key\": \"x@y.z\", \"order_id\": \"812\", \"amount\": 1}):\n        print(json.dumps(coordinator(req), ensure_ascii=False))\n"};
